        a, b = grid[:rowcut], grid[rowcut + 1:]
        out_h, out_w = min(len(a), len(b)), w
    else:
        colcut = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        a = [row[:colcut] for row in grid]
        b = [row[colcut + 1:] for row in grid]
        out_h, out_w = h, min(len(a[0]), len(b[0]))
    counts = {}
